/** Real client/server regression in the existing owned world. */
final class NativeLatestBench {
 static final BlockPos SUPPLY=new BlockPos(-30,64,-25);static CompletableFuture<?> work;
 static int stage,age,unit,building,harvester,supply,supplyCash;static boolean carried;static double riderError;static int riderSamples;static String powerCommand;static Set<Integer> beforePlanes;static double startZ,stoppedZ;static UUID driveCow;static long fireSequence;static boolean began;
 static void prepare(Minecraft mc){work=CompletableFuture.runAsync(()->{var level=NativePolishBench.level(mc);level.setBlock(SUPPLY,SiteBlocks.SUPPLY.defaultBlockState(),3);var sites=WorldSiteStore.get(level);sites.remaining(WorldSiteStore.key(SUPPLY),0);if(sites.sites().stream().noneMatch(s->s.pos().equals(SUPPLY)&&s.cash()==0))throw new IllegalStateException("Missing depleted resource fixture");},mc.getSingleplayerServer());}
 static NativeActorEntity proxy(Minecraft mc,int id){for(var e:mc.level.entitiesForRendering())if(e instanceof NativeActorEntity a&&a.nativeId==id)return a;return null;}
 static void next(int value){stage=value;age=0;local.generalsmc.GeneralsMod.LOG.info("Latest oracle case {}",value);}
 static void begin(Minecraft mc)throws Exception{
  began=true;work.join();unit=NativeReportsBench.unit;var v=NativeWorldView.current;
  NativePolishBench.check(v.state.resources().stream().anyMatch(r->r.key().equals(WorldSiteStore.key(SUPPLY))&&r.cash()>0),"Starting another match replenishes a previously depleted persistent supply marker");
  NativePolishBench.check(v.scene.positions().containsKey(unit)&&v.state.overheadImages().stream().filter(b->b.id()==unit).allMatch(NativeSession.OverheadImage::relative),"Original group and status icons use actor-relative anchors from the same scene frame as the model");
  NativePolishBench.spawn("AmericaSupplyCenter",-50,-25,0);NativePolishBench.spawn("AmericaVehicleChinook",-44,-33,0);
  NativeRtsController.toggle();v.cameraX=-30;v.cameraZ=-25;v.zoom=24;mc.setScreen(new NativePolishBench.Hover(v.session));next(-10);
 }
 static void mount(Minecraft mc){
  work=CompletableFuture.runAsync(()->{var w=NativePolishBench.level(mc);for(var e:w.getAllEntities())if(e instanceof Mob&&!(e instanceof NativeActorEntity))e.discard();var p=w.getServer().getPlayerList().getPlayer(mc.player.getUUID());var body=java.util.stream.StreamSupport.stream(w.getAllEntities().spliterator(),false).filter(e->e instanceof NativeActorEntity a&&a.nativeId==unit).map(e->(NativeActorEntity)e).findFirst().orElseThrow();var box=body.getBoundingBox();p.teleportTo(w,box.maxX+1,body.getY()+.05,body.getZ(),Set.of(),0,0,false);double before=p.getX();p.move(MoverType.SELF,new Vec3(-box.getXsize()-2,0,0));if(before-p.getX()>.8)throw new IllegalStateException("Minecraft player walks through a native vehicle");var cow=new net.minecraft.world.entity.animal.Cow(EntityType.COW,w);cow.setPos(box.maxX+1,body.getY()+.05,body.getZ());double old=cow.getX();cow.move(MoverType.SELF,new Vec3(-box.getXsize()-2,0,0));if(old-cow.getX()>.8)throw new IllegalStateException("Minecraft mob walks through a native vehicle");p.teleportTo(w,box.maxX+.5,body.getY()+1,body.getZ(),Set.of(),0,0,false);},mc.getSingleplayerServer());next(0);
 }

 static boolean tick(Minecraft mc)throws Exception{
  age++;if(age>(stage<0?1200:700))throw new IllegalStateException("Latest regression timeout "+stage);var v=NativeWorldView.current;
  switch(stage){
   case -10->{harvester=NativePolishBench.find("AmericaVehicleChinook");var stock=v.state.resources().stream().filter(r->r.key().equals(WorldSiteStore.key(SUPPLY))).findFirst().orElse(null);if(stock!=null&&harvester>0&&age>30){supply=stock.id();v.session.select(harvester);next(-11);}}
   case -11->{if(age>10&&v.state.selected().contains(harvester)){var screen=(NativePolishBench.Hover)MenuScreens.active(mc.screen);var box=v.bounds(supply);if(box==null)break;var xy=screen.project(box.getCenter());boolean clicked=false;for(int dy=-16;dy<=16&&!clicked;dy+=4)for(int dx=-16;dx<=16&&!clicked;dx+=4){int x=(int)xy[0]+dx,y=(int)xy[1]+dy;if(screen.actorAt(x,y)==supply){screen.scripted=true;screen.px=x;screen.py=y;screen.mouseMoved(x,y);screen.mouseClicked(x,y,0);screen.mouseReleased(x,y,0);clicked=true;}}if(!clicked)throw new IllegalStateException("Supply geometry cannot be picked through the real Minecraft screen");supplyCash=v.state.localCash();next(-12);}}
   case -12->{var a=v.actor(harvester);if(a!=null){var raw=local.generalsmc.GeneralsMod.JSON.fromJson(java.nio.file.Files.readString(v.session.directory.resolve("state.json")),com.google.gson.JsonObject.class);for(var e:raw.getAsJsonArray("objects"))if(e.getAsJsonObject().get("id").getAsInt()==harvester)carried|=e.getAsJsonObject().get("supplyBoxes").getAsInt()>0;if(carried&&v.state.localCash()>supplyCash){NativePolishBench.check(true,"An ordinary Minecraft RTS click orders the Chinook to gather at a persistent supply marker and deposit its load");NativeRtsController.toggle();mount(mc);}}}

   case 0->{if(work.isDone()&&proxy(mc,unit)!=null&&mc.player.distanceToSqr(proxy(mc,unit))<50&&age>20){work.join();mc.gameMode.interact(mc.player,proxy(mc,unit),InteractionHand.MAIN_HAND);next(1);}}
   case 1->{if(mc.player.getVehicle() instanceof NativeActorEntity actor&&actor.nativeId==unit){NativePolishBench.check(true,"Minecraft movement collides with a native mobile unit while its own passenger remains free");NativePolishBench.check(true,"Actual Minecraft entity interaction boards an owned Generals vehicle through the server");startZ=v.actor(unit).y();mc.options.setCameraType(net.minecraft.client.CameraType.THIRD_PERSON_BACK);mc.player.setYRot(0);mc.options.keyUp.setDown(true);next(2);}}
   case 2->{var state=mc.getEntityRenderDispatcher().getRenderer(mc.player).createRenderState(mc.player,.5f);var expected=v.riderPosition(mc.player);if(expected!=null){riderSamples++;riderError=Math.max(riderError,new Vec3(state.x,state.y,state.z).distanceTo(expected));}if(age==25)Screenshot.grab(mc.gameDirectory,"beta22-driving-third-person.png",mc.getMainRenderTarget(),c->{});if(age>35){NativePolishBench.check(riderSamples>20&&riderError<.001,"Third-person passenger render state follows the same interpolated native seat as the vehicle");NativePolishBench.values.put("maxRiderPoseErrorBlocks",riderError);NativePolishBench.check(!NativeDrivingVisual.batches(v,mc).isEmpty(),"A mounted armed vehicle shows its camera-centred weapon impact reticle");mc.options.keyUp.setDown(false);NativePolishBench.check(v.actor(unit).y()>startZ+WorldScale.UNITS_PER_BLOCK,"Minecraft movement binding drives the original vehicle locomotor");next(3);}}
   case 3->{if(age==15)stoppedZ=v.actor(unit).y();if(age>40){NativePolishBench.check(Math.abs(v.actor(unit).y()-stoppedZ)<WorldScale.UNITS_PER_BLOCK,"Releasing movement stops the mounted native vehicle");mc.options.setCameraType(net.minecraft.client.CameraType.FIRST_PERSON);fireSequence=v.state.frame();mc.player.setYRot(90);mc.player.setXRot(20);mc.options.keyAttack.setDown(true);next(30);}}
   case 30->{mc.player.setYRot(90);mc.player.setXRot(20);if(local.generalsmc.GeneralsMod.JSON.fromJson(java.nio.file.Files.readString(v.session.directory.resolve("state.json")),com.google.gson.JsonObject.class).getAsJsonArray("objects").asList().stream().map(e->e.getAsJsonObject()).anyMatch(a->a.get("id").getAsInt()==unit&&a.get("weaponShot").getAsLong()>fireSequence)){mc.options.keyAttack.setDown(false);NativePolishBench.check(true,"Mounted Minecraft attack binding fires the original cannon with its own projectile and cooldown");work=CompletableFuture.runAsync(()->{var w=NativePolishBench.level(mc);var a=v.actor(unit);var location=v.origin.world(a.x(),a.y(),a.z());var cow=new net.minecraft.world.entity.animal.Cow(EntityType.COW,w);cow.setPos(location.x-8,64,location.z);cow.setNoAi(true);cow.setPersistenceRequired();w.addFreshEntity(cow);driveCow=cow.getUUID();},mc.getSingleplayerServer());next(31);}}
   case 31->{if(work.isDone()&&age>20){work.join();var target=java.util.stream.StreamSupport.stream(mc.level.entitiesForRendering().spliterator(),false).filter(e->e.getUUID().equals(driveCow)).findFirst().orElse(null);if(target!=null){var delta=target.position().add(0,target.getBbHeight()*.5,0).subtract(mc.player.getEyePosition().add(v.riderCameraOffset(mc.player,1)));mc.player.setYRot((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)));mc.player.setXRot((float)-Math.toDegrees(Math.atan2(delta.y,delta.horizontalDistance())));mc.options.keyAttack.setDown(true);if(v.session.recentCombatEvents().stream().anyMatch(e->driveCow.toString().equals(e.target()))){mc.options.keyAttack.setDown(false);work=CompletableFuture.runAsync(()->{var cow=(net.minecraft.world.entity.LivingEntity)NativePolishBench.level(mc).getEntity(driveCow);if(cow!=null&&cow.getHealth()>=cow.getMaxHealth())throw new IllegalStateException("Mounted shot did not damage the real Minecraft target");},mc.getSingleplayerServer());NativePolishBench.check(true,"Mounted cannon targets a real Minecraft mob through the original weapon damage path");NativeRtsController.toggle();var a=v.actor(unit);startZ=a.y();v.session.select(unit);v.session.send("MOVE "+a.x()+" "+(a.y()+48)+" "+a.z());next(32);}}}}
   case 32->{if(age>75){NativePolishBench.check(v.actor(unit).y()>startZ+WorldScale.UNITS_PER_BLOCK,"Switching to RTS while mounted releases direct control and preserves commander movement orders");NativeRtsController.toggle();mc.options.keyShift.setDown(true);next(4);}}
   case 4->{if(mc.player.getVehicle()==null&&age>10){mc.options.keyShift.setDown(false);work=CompletableFuture.runAsync(()->{var w=NativePolishBench.level(mc);var actor=java.util.stream.StreamSupport.stream(w.getAllEntities().spliterator(),false).filter(e->e instanceof NativeActorEntity a&&a.nativeId==unit).map(e->(NativeActorEntity)e).findFirst().orElseThrow();var arrow=new Arrow(EntityType.ARROW,w);arrow.setPos(actor.getX()-7,actor.getY()+actor.getBbHeight()*.5,actor.getZ());arrow.setNoGravity(true);arrow.setDeltaMovement(.8,0,0);w.addFreshEntity(arrow);},mc.getSingleplayerServer());NativePolishBench.check(true,"Minecraft sneak binding dismounts the native vehicle");next(5);}}
   case 5->{var actor=proxy(mc,unit);if(work.isDone()&&actor!=null&&actor.getArrowCount()>0&&!actor.stuckArrows().isEmpty()){work.join();NativePolishBench.check(new NativeArrowVisual().batches(v,mc).stream().anyMatch(b->b.texture()==-1),"A real Minecraft arrow sticks into a native unit and produces triangle-anchored arrow geometry");NativeRtsController.toggle();var a=v.actor(unit);var p=v.origin.world(a.x(),a.y(),a.z());v.cameraX=p.x;v.cameraZ=p.z;v.zoom=10;v.cameraYaw=0;next(51);}}
   case 51->{if(age>40){Screenshot.grab(mc.gameDirectory,"beta21-driving-arrow.png",mc.getMainRenderTarget(),c->{});work=CompletableFuture.runAsync(()->{var w=NativePolishBench.level(mc);var body=java.util.stream.StreamSupport.stream(w.getAllEntities().spliterator(),false).filter(e->e instanceof NativeActorEntity a&&a.nativeId==unit).map(e->(NativeActorEntity)e).findFirst().orElseThrow();float health=body.getHealth();w.explode(null,body.getX()-1,body.getY()+.5,body.getZ(),.75f,net.minecraft.world.level.Level.ExplosionInteraction.NONE);if(body.getHealth()>=health)throw new IllegalStateException("Minecraft explosion no longer damages mobile native units");},mc.getSingleplayerServer());next(52);}}
   case 52->{if(work.isDone()){work.join();NativePolishBench.check(true,"Minecraft explosions still damage mobile units after restoring their physical collision");NativePolishBench.spawn("AmericaCommandCenter",64.5,-18.5,Math.PI/4);next(6);}}
   case 6->{building=NativePolishBench.find("AmericaCommandCenter");if(building>0&&proxy(mc,building)!=null&&age>30){NativePolishBench.check(mc.hitResult==null&&mc.crosshairPickEntity==null,"RTS entry clears Minecraft block selection on every rendered frame");NativePolishBench.collider=building;work=CompletableFuture.runAsync(()->NativePolishBench.collision(mc),mc.getSingleplayerServer());v.cameraX=64.5;v.cameraZ=-18.5;v.zoom=34;mc.getEntityRenderDispatcher().setRenderHitBoxes(true);next(7);}}
   case 7->{if(work.isDone()&&age>20){work.join();NativePolishBench.check(!NativeFootprintVisual.batches(v,mc).isEmpty(),"F3+B draws the rotated native footprint; its empty bounding-box corners remain walkable and buildable");Screenshot.grab(mc.gameDirectory,"beta21-oriented-collision.png",mc.getMainRenderTarget(),c->{});v.fog.enabled(true);v.cameraX=110;v.cameraZ=110;v.zoom=25;mc.setScreen(new NativePolishBench.Hover(v.session));v.session.send("DEBUG_SCIENCES");v.session.send("DEBUG_COOLDOWN 0");v.session.select(NativeReportsBench.base);next(8);}}
   case 8->{if(age>30&&mc.level.hasChunkAt(new BlockPos(110,64,110))){mc.getEntityRenderDispatcher().setRenderHitBoxes(false);NativePolishBench.check(v.fog.at(110,110)>=80,"General power target is in never-explored fog");var control=v.state.controls().stream().filter(c->c.enabled()&&c.command()!=null&&c.command().contains("A10")).findFirst().orElse(null);if(control==null){if(age>120)throw new IllegalStateException("Missing A10 control: "+v.state.controls());break;}powerCommand=control.command();((NativeWorldScreen)MenuScreens.active(mc.screen)).clickCommand(powerCommand,true);next(9);}}
   case 9->{if(age>5){((NativeWorldScreen)MenuScreens.active(mc.screen)).clickCommand(powerCommand,false);next(10);}}
   case 10->{if(age>15){NativePolishBench.check(v.state.pendingCommand().contains("A10"),"Original general-power button enters its targeting mode");beforePlanes=new HashSet<>();for(var a:v.state.objects())if(a.template().contains("A10"))beforePlanes.add(a.id());var screen=(NativePolishBench.Hover)MenuScreens.active(mc.screen);var xy=screen.project(new Vec3(110.5,64.01,110.5));screen.px=(int)xy[0];screen.py=(int)xy[1];screen.scripted=true;screen.mouseMoved(screen.px,screen.py);screen.mouseClicked(screen.px,screen.py,0);screen.mouseReleased(screen.px,screen.py,0);next(11);}}
   case 11->{if(v.state.objects().stream().anyMatch(a->a.template().contains("A10")&&!beforePlanes.contains(a.id()))){NativePolishBench.check(true,"Actual original A10 general-power click launches aircraft into never-explored fog");return true;}}
  }return false;
 }
}
